"use client";

import { useEffect, useRef, useState } from "react";

const words = ["fast", "alive", "honest", "effortless", "yours"];
const tints = ["#38bdf8", "#f472b6", "#fbbf24", "#34d399", "#a78bfa"];

export function ScrollWordSwapTailwind() {
  const ref = useRef(null);
  const [active, setActive] = useState(0);
  useEffect(() => {
    const el = ref.current;
    const update = () => {
      const max = el.scrollHeight - el.clientHeight;
      const p = max > 0 ? el.scrollTop / max : 0;
      setActive(Math.min(words.length - 1, Math.floor(p * words.length)));
    };
    el.addEventListener("scroll", update, { passive: true });
    return () => el.removeEventListener("scroll", update);
  }, []);
  return (
    <div ref={ref} tabIndex={0} className="h-[380px] w-full overflow-y-auto rounded-[20px] border border-zinc-800 bg-zinc-900 text-zinc-100">
      <div style={{ height: 380 + words.length * 266 }}>
        <div className="sticky top-0 grid h-[380px] place-items-center px-10 transition-colors duration-700" style={{ background: `radial-gradient(70% 85% at 50% 115%, ${tints[active]}66, transparent 70%)` }}>
          <h3 className="text-center text-5xl font-bold tracking-tight">
            Interfaces that feel{" "}
            <span className="relative inline-block h-[1.2em] overflow-hidden align-bottom">
              <span className="invisible">effortless</span>
              {words.map((w, i) => (
                <span key={w} style={{ color: tints[i] }} className={`absolute left-0 top-0 transition-transform duration-500 ${i === active ? "translate-y-0" : i < active ? "-translate-y-full" : "translate-y-full"}`}>{w}</span>
              ))}
            </span>
            .
          </h3>
        </div>
      </div>
    </div>
  );
}
